fn add(a: i64, b: i64) -> i64 {
    a + b
}

fn main() {
    // Test case 1: Two positive numbers
    let result_pos = add(5, 7);
    assert_eq!(result_pos, 12);

    // Test case 2: One negative and one positive number (edge case)
    let result_mixed = add(-10, 3);
    assert_eq!(result_mixed, -7);

    // Test case 3: Two negative numbers (edge case)
    let result_neg = add(-5, -5);
    assert_eq!(result_neg, -10);

    // Test case 4: Adding zero (identity element)
    let result_zero = add(99, 0);
    assert_eq!(result_zero, 99);

    println!("All addition tests passed successfully.");
}
